1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7	
8		"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
9	)
10	
11	// Process exit codes for the data commands.
12	const (
13		exitOK    = 0
14		exitRule  = 1 // business rule failure (not found, conflict, frozen, …)
15		exitUsage = 2 // bad command line
16		exitData  = 3 // storage cannot be read safely (corrupt/truncated/bad format)
17	)
18	
19	// dataCommands is the set of commands backed by a persistent data directory.
20	var dataCommands = map[string]bool{
21		"circuit-create":    true,
22		"circuit-update":    true,
23		"circuit-freeze":    true,
24		"circuit-get":       true,
25		"circuit-list":      true,
26		"setup-record":      true,
27		"setup-get":         true,
28		"job-submit":        true,
29		"job-get":           true,
30		"job-list":          true,
31		"constraint-import": true,
32		"circuit-compile":   true,
33		"input-check":       true,
34	}
35	
36	// dispatchDataCommand runs cmd with args. handled is false when cmd is not a
37	// data command, so the caller keeps the historical "unknown command" path.
38	func dispatchDataCommand(cmd string, args []string) (code int, handled bool) {
39		if !dataCommands[cmd] {
40			return exitUsage, false
41		}
42		return runDataCommand(cmd, args), true
43	}
44	
45	func runDataCommand(cmd string, args []string) int {
46		fs, f := newFlagSet(cmd, os.Stderr)
47		if err := fs.Parse(args); err != nil {
48			return exitUsage
49		}
50		if len(fs.Args()) > 0 {
51			fmt.Fprintf(os.Stderr, "error: %s does not accept positional arguments (got %q)\n", cmd, fs.Args()[0])
52			return exitUsage
53		}
54		if f.dir == "" {
55			fmt.Fprintf(os.Stderr, "error: --dir is required for %s\n", cmd)
56			return exitUsage
57		}
58	
59		switch cmd {
60		case "circuit-create":
61			return cmdCircuitCreate(f)
62		case "circuit-update":
63			return cmdCircuitUpdate(f)
64		case "circuit-freeze":
65			return cmdCircuitFreeze(f)
66		case "circuit-get":
67			return cmdCircuitGet(f)
68		case "circuit-list":
69			return cmdCircuitList(f)
70		case "setup-record":
71			return cmdSetupRecord(f)
72		case "setup-get":
73			return cmdSetupGet(f)
74		case "job-submit":
75			return cmdJobSubmit(f)
76		case "job-get":
77			return cmdJobGet(f)
78		case "job-list":
79			return cmdJobList(f)
80		case "constraint-import":
81			return cmdConstraintImport(f)
82		case "circuit-compile":
83			return cmdCircuitCompile(f)
84		case "input-check":
85			return cmdInputCheck(f)
86		}
87		return exitUsage
88	}
89	
90	func requireNameVersion(cmd string, f *cliFlags) (bool, int) {
91		if f.name == "" {
92			fmt.Fprintf(os.Stderr, "error: --name is required for %s\n", cmd)
93			return false, exitUsage
94		}
95		if f.version <= 0 {
96			fmt.Fprintf(os.Stderr, "error: --version must be a positive integer for %s\n", cmd)
97			return false, exitUsage
98		}
99		return true, exitOK
100	}
101	
102	func openStore(f *cliFlags) (*zkcircuit.Store, int) {
103		store, err := zkcircuit.Open(f.dir)
104		if err != nil {
105			return nil, reportStoreError(err)
106		}
107		return store, exitOK
108	}
109	
110	// reportStoreError prints a failed storage/domain call and returns the exit
111	// code. Rule failures are 1; unreadable data is 3.
112	func reportStoreError(err error) int {
113		if errors.Is(err, zkcircuit.ErrDataCorrupt) {
114			fmt.Fprintf(os.Stderr, "error: read failed: %v\n", err)
115			return exitData
116		}
117		var domainErr zkcircuit.StoreError
118		if errors.As(err, &domainErr) {
119			fmt.Fprintf(os.Stderr, "error: %v\n", err)
120			return exitRule
121		}
122		fmt.Fprintf(os.Stderr, "error: storage failure: %v\n", err)
123		return exitData
124	}
125	
126	func circuitFromFlags(f *cliFlags) zkcircuit.Circuit {
127		return zkcircuit.Circuit{
128			Name: f.name, Version: f.version,
129			Constraints: f.constraints, PublicInputs: f.publicIn, PrivateInputs: f.privateIn,
130			Description: f.description,
131		}
132	}
133	
134	func formatCircuit(c zkcircuit.Circuit) string {
135		return fmt.Sprintf("name=%s version=%d constraints=%d public_inputs=%d private_inputs=%d frozen=%t description=%q",
136			c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Frozen, c.Description)
137	}
138	
139	func formatJob(j zkcircuit.Job) string {
140		s := fmt.Sprintf("id=%s circuit=%s version=%d kind=%s attempt=%d", j.ID, j.Circuit, j.Version, j.Kind, j.Attempt)
141		if j.Artifact != "" {
142			s += " artifact=" + fmt.Sprintf("%q", j.Artifact)
143		}
144		return s
145	}
146	
147	func cmdCircuitCreate(f *cliFlags) int {
148		if ok, code := requireNameVersion("circuit-create", f); !ok {
149			return code
150		}
151		store, code := openStore(f)
152		if store == nil {
153			return code
154		}
155		defer store.Close()
156	
157		c, err := store.CreateCircuit(circuitFromFlags(f))
158		if err != nil {
159			return reportStoreError(err)
160		}
161		fmt.Println("circuit version:", formatCircuit(c))
162		return exitOK
163	}
164	
165	func cmdCircuitUpdate(f *cliFlags) int {
166		if ok, code := requireNameVersion("circuit-update", f); !ok {
167			return code
168		}
169		store, code := openStore(f)
170		if store == nil {
171			return code
172		}
173		defer store.Close()
174	
175		c, err := store.UpdateCircuit(circuitFromFlags(f))
176		if err != nil {
177			return reportStoreError(err)
178		}
179		fmt.Println("circuit updated:", formatCircuit(c))
180		return exitOK
181	}
182	
183	func cmdCircuitFreeze(f *cliFlags) int {
184		if ok, code := requireNameVersion("circuit-freeze", f); !ok {
185			return code
186		}
187		store, code := openStore(f)
188		if store == nil {
189			return code
190		}
191		defer store.Close()
192	
193		c, err := store.FreezeCircuit(f.name, f.version)
194		if err != nil {
195			return reportStoreError(err)
196		}
197		fmt.Println("circuit frozen:", formatCircuit(c))
198		return exitOK
199	}
200	
201	func cmdCircuitGet(f *cliFlags) int {
202		if ok, code := requireNameVersion("circuit-get", f); !ok {
203			return code
204		}
205		store, code := openStore(f)
206		if store == nil {
207			return code
208		}
209		defer store.Close()
210	
211		c, err := store.GetCircuit(f.name, f.version)
212		if err != nil {
213			return reportStoreError(err)
214		}
215		fmt.Println("circuit:", formatCircuit(c))
216		return exitOK
217	}
218	
219	func cmdCircuitList(f *cliFlags) int {
220		store, code := openStore(f)
221		if store == nil {
222			return code
223		}
224		defer store.Close()
225	
226		circuits, err := store.ListCircuits()
227		if err != nil {
228			return reportStoreError(err)
229		}
230		for _, c := range circuits {
231			fmt.Println("circuit:", formatCircuit(c))
232		}
233		return exitOK
234	}
235	
236	func cmdSetupRecord(f *cliFlags) int {
237		if ok, code := requireNameVersion("setup-record", f); !ok {
238			return code
239		}
240		store, c := openStore(f)
241		if store == nil {
242			return c
243		}
