		t.Fatal(err)
	}
	bad := append(bytes.Clone(original), []byte("{{not-json")...)
	if err := os.WriteFile(dataFile, bad, 0o644); err != nil {
		t.Fatal(err)
	}
	code, _, errOut := r("circuit-list", "--dir", dir)
