315			t.Fatalf("version drift resubmit: want conflict, got %v", err)
316		}
317		got, _ := s.GetJob("job-1")
318		if got.Attempt != 2 || got.Version != 1 {
319			t.Fatalf("conflicting resubmit mutated stored job: %+v", got)
320		}
321	
322		// Later circuit versions never change what the stored job binds to.
323		readyCircuit(t, s, "c", 2)
324		got, _ = s.GetJob("job-1")
325		if got.Circuit != "c" || got.Version != 1 {
326			t.Fatalf("job binding drifted: %+v", got)
327		}
328		jobs, _ := s.ListJobs()
329		if len(jobs) != 1 {
330			t.Fatalf("want exactly one job, got %+v", jobs)
331		}
